        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Incontro papa-Rubio: cala la tensione, restano le divergenze",
        "testo_it": "Incontro Papa-Rubio: distensione diplomatica nonostante le divergenze tra Santa Sede e amministrazione USA.",
        "priorita": "Alta",
